import{_ as r,C as n,o as l,c as g,ag as s,E as o,j as t,a as i}from"./chunks/framework.CtWPcAmt.js";const w=JSON.parse('{"title":"Magic AI for Sellers","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/magic-ai.md","filePath":"catalog/magic-ai.md","lastUpdated":1786111645000}'),d={name:"catalog/magic-ai.md"};function c(p,e,u,h,m,f){const a=n("ImagePopup");return l(),g("div",null,[e[0]||(e[0]=s('<h1 id="magic-ai-for-sellers" tabindex="-1">Magic AI for Sellers <a class="header-anchor" href="#magic-ai-for-sellers" aria-label="Permalink to &quot;Magic AI for Sellers&quot;">​</a></h1><p><strong>Magic AI</strong> lets sellers draft product content — descriptions, other attributes, and suggested categories — with AI, straight from the product form, instead of writing everything by hand. The admin controls who can use it and how often.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>What Magic AI generates and where</li><li>How the admin enables it and sets limits</li><li>How a seller uses it, step by step</li></ul></div><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>When Magic AI is enabled, a <strong>Generate content</strong> button appears in the <strong>product edit form header</strong>. From a short description you write — and, if allowed, reference photos you attach for the AI to read — it proposes values for the listing&#39;s fields and suggests categories, which you review and apply. Magic AI does not create images; it only reads the reference photos you provide. Nothing is saved until you save the product.</p><h2 id="enabling-magic-ai-admin" tabindex="-1">Enabling Magic AI (admin) <a class="header-anchor" href="#enabling-magic-ai-admin" aria-label="Permalink to &quot;Enabling Magic AI (admin)&quot;">​</a></h2><p>Magic AI is off until the admin turns it on. It&#39;s controlled in a few places:</p><ul><li><strong>Globally</strong>, under <strong>Configure → Magic AI</strong>, where the AI provider credentials, model, and product-content options are set (including whether sellers may attach <strong>reference images</strong>, how many, and which attributes are in scope).</li><li><strong>Per seller</strong>, on the seller&#39;s admin edit form: <strong>Magic AI Enabled</strong> and a <strong>Magic AI Generation Limit</strong> for that seller.</li><li><strong>Limits</strong> — each seller gets a generation quota over a <strong>period</strong> (daily by default, or monthly). Usage is recorded only on a <strong>successful</strong> generation, so a failed attempt never costs a generation.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Magic AI needs a valid AI provider configured under <strong>Configure → Magic AI</strong>. Without working credentials the <strong>Generate content</strong> button won&#39;t run — even if it&#39;s enabled for the seller.</p></div><h2 id="using-magic-ai-seller" tabindex="-1">Using Magic AI (seller) <a class="header-anchor" href="#using-magic-ai-seller" aria-label="Permalink to &quot;Using Magic AI (seller)&quot;">​</a></h2><p>On a product&#39;s edit form, select <strong>Generate content</strong> to open the Magic AI dialog:</p>',11)),o(a,{src:"/images/magic-ai/generate.png",alt:"Magic AI Generate content dialog — describe your product, reference images, and fields to fill"}),e[1]||(e[1]=s("<ol><li><strong>Describe your product</strong> — write a short description (this is the prompt). Optionally attach <strong>reference images</strong>, and — where the admin allows it — pick exactly <strong>which fields</strong> to fill; eligible fields come pre-selected. Whether fields you&#39;ve already filled are included depends on the admin&#39;s <strong>Overwrite Filled Attributes</strong> setting.</li><li><strong>Generating</strong> — Magic AI drafts the content.</li><li><strong>Review</strong> — each proposed field is shown as a card marked <strong>new</strong> or <strong>replaces</strong>, with the previous value struck through; suggested <strong>categories</strong> appear too. You can <strong>Regenerate</strong> any single field, and skipped items explain why. A running meter shows how many generations you&#39;ve used against your limit.</li></ol>",1)),o(a,{src:"/images/magic-ai/generated.png",alt:"Magic AI review step — proposed fields marked new or replaces, with previous values struck through"}),e[2]||(e[2]=t("ol",{start:"4"},[t("li",null,[t("strong",null,"Apply"),i(" — applying only "),t("strong",null,"fills the form"),i(" (and ticks suggested categories; if you opted in, your uploaded reference photos are reused as the product's images). The listing is still a draft until you save it, and it goes through the normal "),t("a",{href:"/catalog/product-management#drafts-submission-and-approval"},"approval flow"),i(".")])],-1)),o(a,{src:"/images/magic-ai/applied.png",alt:"Magic AI confirmation — fields updated on the product form, pending save"}),e[3]||(e[3]=t("p",null,"If you've used your whole quota, the dialog tells you when it resets; if there's nothing left to fill, it says so.",-1)),e[4]||(e[4]=t("div",{class:"tip custom-block"},[t("p",{class:"custom-block-title"},"TIP"),t("p",null,"Write a specific, factual description — materials, size, use, audience. The better your prompt, the less editing the drafted content needs before you submit for approval.")],-1))])}const b=r(d,[["render",c]]);export{w as __pageData,b as default};
